/* GENERATED by tools/split-map.js from film-engine/src/index.html: the code only titles uses. Do not edit; edit the source or the tool. */


    // ══════════════════════════════════════════════════════════════
    // TITLES, CREDITS AND SUBTITLES
    //
    // Three delivery surfaces whose routes shipped with the delivery work and
    // whose pages never did, so every field they accept -- a credit's role and
    // character name, a card's type and hold, a cue's language, speaker,
    // position and style -- could only be written by curl or by an agent.
    //
    // Vocabularies are SERVED, never typed here: `sections` and `card_types`
    // come back with the list, on the same rule as the card vocabulary and the
    // licence statuses. A page holding its own copy offers values the route
    // refuses the first time somebody adds one, and the refusal reads as saving
    // being broken.
    // ══════════════════════════════════════════════════════════════
    let TITLE_VOCAB = { sections: [], card_types: [] };

    async function loadTitles() {
        if (!state.currentProject) return;
        const pid = state.currentProject.id;
        try {
            const [credits, cards] = await Promise.all([
                api(`/projects/${pid}/credits`),
                api(`/projects/${pid}/title-cards`),
            ]);
            TITLE_VOCAB = { sections: credits.sections || [], card_types: cards.card_types || [] };
            renderTitleCards(cards.title_cards || []);
            renderCredits(credits.credits || []);
        } catch (err) {
            document.getElementById('creditList').innerHTML =
                `<p class="text-sm text-muted">Could not read the titles: ${esc(err.message)}</p>`;
        }
    }

    function renderTitleCards(cards) {
        const host = document.getElementById('titleCardList');
        if (!cards.length) {
            host.innerHTML = '<p class="text-sm text-muted">No title cards. A main title and an end title are '
                + 'the two most films have.</p>';
            return;
        }
        host.innerHTML = cards.map(c => `
            <div class="card" style="margin-bottom:8px;">
                <div class="flex-between" style="gap:8px;flex-wrap:wrap;min-width:0;">
                    <div style="min-width:0;">
                        <strong>${esc(c.text || 'Untitled card')}</strong>
                        ${c.subtext ? `<div class="text-sm text-muted">${esc(c.subtext)}</div>` : ''}
                        <div class="tag-row" style="margin-top:4px;">
                            <span class="badge">${esc((c.card_type || 'card').replace(/_/g, ' '))}</span>
                            <span class="tag">${((c.duration_ms || 0) / 1000).toFixed(1)}s</span>
                            ${c.position_in_timeline ? `<span class="tag">${esc(c.position_in_timeline)}</span>` : ''}
                        </div>
                    </div>
                    <div class="card-actions">
                        <button class="btn btn-secondary btn-sm" onclick="openTitleCard('${c.id}')">Edit</button>
                        <button class="btn btn-secondary btn-sm" onclick="deleteTitleCard('${c.id}')">Delete</button>
                    </div>
                </div>
            </div>`).join('');
    }

    function renderCredits(credits) {
        const host = document.getElementById('creditList');
        if (!credits.length) {
            host.innerHTML = '<p class="text-sm text-muted">No credits yet.</p>';
            return;
        }
        // Grouped by section in the served order, so the page reads the way the
        // roll does rather than alphabetically.
        const order = TITLE_VOCAB.sections.length ? TITLE_VOCAB.sections
            : [...new Set(credits.map(c => c.section))];
        host.innerHTML = order.filter(sec => credits.some(c => c.section === sec)).map(sec => `
            <h4 style="margin:12px 0 6px;text-transform:capitalize;">${esc(sec.replace(/_/g, ' '))}</h4>
            ${credits.filter(c => c.section === sec).map(c => `
                <div class="card" style="margin-bottom:6px;">
                    <div class="flex-between" style="gap:8px;flex-wrap:wrap;min-width:0;">
                        <div style="min-width:0;">
                            <strong>${esc(c.name || '')}</strong>
                            ${c.role ? `<span class="text-sm text-muted"> &mdash; ${esc(c.role)}</span>` : ''}
                            ${c.character_name ? `<div class="text-sm text-muted">as ${esc(c.character_name)}</div>` : ''}
                        </div>
                        <div class="card-actions">
                            <button class="btn btn-secondary btn-sm" onclick="openCredit('${c.id}')">Edit</button>
                            <button class="btn btn-secondary btn-sm" onclick="deleteCredit('${c.id}')">Delete</button>
                        </div>
                    </div>
                </div>`).join('')}`).join('');
    }

    function openCredit(id) {
        const c = id ? (state.creditRows || []).find(x => x.id === id) || {} : {};
        showModalHtml('creditModal', `
            <div class="modal-header">
                <h3>${id ? 'Edit credit' : 'New credit'}</h3>
                <button class="modal-close" onclick="closeModal('creditModal')">&times;</button>
            </div>
            <div class="modal-body">
                <div class="form-group"><label>Name</label>
                    <input type="text" id="creditName" data-field="name" maxlength="200" value="${esc(c.name || '')}"
                           placeholder="The person or company"></div>
                <div class="form-group"><label>Section</label>
                    <select id="creditSection" data-field="section">${vocabOptions(TITLE_VOCAB.sections, c.section || 'crew')}</select></div>
                <div class="form-group"><label>Role</label>
                    <input type="text" id="creditRole" data-field="role" maxlength="200" value="${esc(c.role || '')}"
                           placeholder="e.g. Director of Photography"></div>
                <div class="form-group"><label>Character</label>
                    <input type="text" id="creditCharacter" data-field="character_name" maxlength="200"
                           value="${esc(c.character_name || '')}" placeholder="For a cast credit — who they played">
                    <span class="text-sm text-muted">Cast only. A crew credit leaves this blank.</span></div>
                <div class="form-group"><label>Style</label>
                    <input type="text" id="creditStyle" data-field="style" maxlength="500" value="${esc(c.style || '')}"
                           placeholder="How it is set — read by the export, not by a generator"></div>
                <div class="form-group"><label>Order within the section</label>
                    <input type="number" id="creditOrder" data-field="sort_order" min="0" value="${c.sort_order || 0}"></div>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeModal('creditModal')">Cancel</button>
                <button class="btn btn-primary" onclick="saveCredit(${id ? `'${id}'` : 'null'})">Save</button>
            </div>`);
    }

    async function saveCredit(id) {
        const v = i => (document.getElementById(i) || {}).value;
        const body = {
            name: v('creditName'), section: v('creditSection'), role: v('creditRole'),
            character_name: v('creditCharacter'), style: v('creditStyle'),
            sort_order: Number(v('creditOrder')) || 0,
        };
        if (!body.name) return setStatus('A credit needs a name');
        try {
            await api(id ? `/credits/${id}` : `/projects/${state.currentProject.id}/credits`,
                { method: id ? 'PUT' : 'POST', body: JSON.stringify(body) });
            closeModal('creditModal');
            setStatus(id ? 'Credit updated' : 'Credit added');
            loadTitles();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteCredit(id) {
        if (!confirm('Remove this credit?')) return;
        try { await api(`/credits/${id}`, { method: 'DELETE' }); loadTitles(); setStatus('Credit removed'); }
        catch (err) { setStatus('Error: ' + err.message); }
    }

    function openTitleCard(id) {
        const c = id ? (state.titleCardRows || []).find(x => x.id === id) || {} : {};
        showModalHtml('titleCardModal', `
            <div class="modal-header">
                <h3>${id ? 'Edit title card' : 'New title card'}</h3>
                <button class="modal-close" onclick="closeModal('titleCardModal')">&times;</button>
            </div>
            <div class="modal-body">
                <div class="form-group"><label>Text</label>
                    <input type="text" id="cardText" data-field="text" maxlength="500" value="${esc(c.text || '')}"
                           placeholder="What the card says"></div>
                <div class="form-group"><label>Subtext</label>
                    <input type="text" id="cardSubtext" data-field="subtext" maxlength="500" value="${esc(c.subtext || '')}"
                           placeholder="A second line, smaller"></div>
                <div class="form-group"><label>Type</label>
                    <select id="cardType" data-field="card_type">${vocabOptions(TITLE_VOCAB.card_types, c.card_type || 'card')}</select></div>
                <div class="form-group"><label>Hold (seconds)</label>
                    <input type="number" id="cardDuration" data-field="duration_ms" min="0" step="0.1"
                           value="${((c.duration_ms || 3000) / 1000).toFixed(1)}">
                    <span class="text-sm text-muted">Stored in milliseconds; typed in seconds, which is how a card is read.</span></div>
                <div class="form-group"><label>Where it sits</label>
                    <input type="text" id="cardPosition" data-field="position_in_timeline" maxlength="100"
                           value="${esc(c.position_in_timeline || '')}" placeholder="e.g. before scene 1, or after the last shot"></div>
                <div class="form-group"><label>Style</label>
                    <input type="text" id="cardStyle" data-field="style" maxlength="500" value="${esc(c.style || '')}"></div>
                <div class="form-group"><label>Order</label>
                    <input type="number" id="cardOrder" data-field="sort_order" min="0" value="${c.sort_order || 0}"></div>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeModal('titleCardModal')">Cancel</button>
                <button class="btn btn-primary" onclick="saveTitleCard(${id ? `'${id}'` : 'null'})">Save</button>
            </div>`);
    }

    async function saveTitleCard(id) {
        const v = i => (document.getElementById(i) || {}).value;
        const body = {
            text: v('cardText'), subtext: v('cardSubtext'), card_type: v('cardType'),
            duration_ms: Math.round((Number(v('cardDuration')) || 0) * 1000),
            position_in_timeline: v('cardPosition'), style: v('cardStyle'),
            sort_order: Number(v('cardOrder')) || 0,
        };
        if (!body.text) return setStatus('A title card needs its text');
        try {
            await api(id ? `/title-cards/${id}` : `/projects/${state.currentProject.id}/title-cards`,
                { method: id ? 'PUT' : 'POST', body: JSON.stringify(body) });
            closeModal('titleCardModal');
            setStatus(id ? 'Title card updated' : 'Title card added');
            loadTitles();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteTitleCard(id) {
        if (!confirm('Remove this title card?')) return;
        try { await api(`/title-cards/${id}`, { method: 'DELETE' }); loadTitles(); setStatus('Title card removed'); }
        catch (err) { setStatus('Error: ' + err.message); }
    }
